function chuanHoaSdt(raw) {
  if (raw === null || raw === undefined) return { sdt: '', hopLe: false };
  const goc = String(raw).trim();
  const coDauCong = goc.startsWith('+');
  let s = goc.replace(/\D/g, '');
  if (s.startsWith('00')) s = s.slice(2);
  if (s.startsWith('84') && (coDauCong || s.length >= 11)) s = s.slice(2);
  if (!s.startsWith('0')) s = '0' + s;
  s = s.replace(/^0{2,}/, '0');
  return { sdt: s, hopLe: /^0\d{9,10}$/.test(s) };
}

// Danh sach nguon hop le. Nguon la khong co trong day se thanh "khac".
const NGUON_HOP_LE = ['facebook_ads','zalo_oa','website','trang_tour','tiktok','hotline','gioi_thieu','khac'];

// Gio Viet Nam, dang YYYY-MM-DD HH:mm:ss
function gioVN(t) {
  return new Date(t).toLocaleString('sv-SE', { timeZone: 'Asia/Ho_Chi_Minh' });
}

const ra = [];
for (const item of $input.all()) {
  // Webhook dat du lieu trong body. Nguon khac co the gui thang.
  const b = item.json.body ?? item.json;

  // ANH XA TEN TRUONG. Them ten moi vao day khi noi them mot nguon lead.
  const hoTen  = b.ho_ten ?? b.full_name ?? b.name ?? b.ten ?? '';
  const sdtRaw = b.sdt ?? b.phone ?? b.phone_number ?? b.so_dien_thoai ?? '';
  const email  = b.email ?? '';
  const nguon  = String(b.nguon ?? b.source ?? 'khac').toLowerCase().trim();
  const maCD   = b.ma_chien_dich ?? b.campaign_id ?? '';
  const khoa   = b.khoa_quan_tam ?? b.course ?? '';
  const ghiChu = b.ghi_chu ?? b.note ?? '';

  const p = chuanHoaSdt(sdtRaw);
  const now = gioVN(Date.now());

  ra.push({ json: {
    ho_ten: String(hoTen).trim() || 'Chua ro ten',
    sdt: p.sdt,
    sdt_goc: String(sdtRaw),
    sdt_khong_hop_le: p.hopLe ? '' : 'x',
    email: String(email).trim(),
    nguon: NGUON_HOP_LE.includes(nguon) ? nguon : 'khac',
    ma_chien_dich: String(maCD),
    khoa_quan_tam: String(khoa),
    ghi_chu: String(ghiChu),
    thoi_gian_vao: now,
    trang_thai: 'moi',
    thoi_gian_goi_dau: '',
    ly_do_mat: '',
    khoa_dang_ky: '',
    so_tien_da_thu: '',
    lop_id: '',
    tao_luc: now,
    cap_nhat_luc: now,
  }});
}
return ra;

// DANH SACH TU VAN VIEN. Sua o day khi them bot nguoi.
// Ten phai trung voi cot nguoi_phu_trach trong bang LEAD.
const TU_VAN_VIEN = ['Tu van vien A', 'Tu van vien B', 'Tu van vien C', 'Tu van vien D'];

const lead = $('Chuan hoa du lieu').first().json;

// Cac dong dang co trong bang LEAD. Loc bo dong rong.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.sdt);
const soLead = rows.length;

// Chi chong trung khi so hop le. So sai dinh dang van tao lead moi.
const trung = lead.sdt_khong_hop_le
  ? null
  : rows.find((r) => String(r.sdt).trim() === lead.sdt) || null;

if (trung) {
  // Khach quay lai. Khong tao lead moi, chi ghi mot dong hoat dong.
  return [{ json: {
    la_lead_moi: false,
    id: 'HD' + String(Date.now()).slice(-8),
    lead_id: trung.lead_id || '',
    loai: 'ghi_chu',
    noi_dung: 'Khach quay lai tu nguon ' + lead.nguon + '. Trang thai dang la ' + (trung.trang_thai || 'chua ro') + '.',
    nguoi_thuc_hien: 'he_thong',
    thoi_gian: lead.thoi_gian_vao,
    trang_thai_cu: trung.trang_thai || '',
    nguoi_phu_trach_cu: trung.nguoi_phu_trach || '',
  }}];
}

// Lead moi. Gan tu van vien luan phien theo so lead da co.
const nguoi = TU_VAN_VIEN[soLead % TU_VAN_VIEN.length];

return [{ json: {
  ...lead,
  la_lead_moi: true,
  lead_id: 'L' + String(soLead + 1).padStart(5, '0'),
  nguoi_phu_trach: nguoi,
}}];
